scripts.过夜.txt:
// 在碧霞岛山洞内过夜

	Sleep(1000);
	FadeOut();
	SaveNpc();
	SaveObj();
	StopMusic();
	PlayMusic("夜色.mp3"); 
	LoadMap("map038_碧霞岛山洞.map");
	ChangeMapColor(255, 255, 255);
	ChangeAsfColor(255, 255, 255);
	LoadNpc("map038_event130.npc");
	LoadObj("map038_event130.obj");
	SetNpcActionFile("独孤剑", 0, "mpc007_2.asf");
	SetNpcActionFile("独孤剑", 1, "mpc007_2.asf");
	SetPlayerPos(7, 24);
	SetPlayerDir(3);
	DelNpc("张琳心");
	AddNpc("npc004_张琳心倒地2.ini", 6, 22, 7);
	FadeIn();
	Say("回到山洞，独孤剑望着依然昏迷不醒的张琳心，忽然发觉自己距离一个女孩这么近，心中突然产生出了一种从来没有过的感觉。");
	Sleep(1000);
	FadeOut();
	Say("夜渐渐深了，虽然山洞外海风呼啸，可是洞内却在篝火的映照下温暖如春，不知过了多久，绿衣少女悠悠醒转过来。");
	Sleep(1000);
	SetNpcActionFile("独孤剑", 0, "npc001_st2.asf");
	SetNpcActionFile("独孤剑", 1, "npc001_sst2.asf");
	SetPlayerPos(7, 26);
	SetPlayerDir(1);
	FadeIn();
	Sleep(500);
	
	SetNpcActionFile("张琳心", 0, "mpc005_2.asf");  
	SetNpcActionFile("张琳心", 1, "mpc005_2.asf");
	NpcSpecialAction("张琳心", "mpc005_1.asf");
	Sleep(2000);
	
	SetPlayerDir(3);
	PlayerGoto(7, 24);
	SetPlayerDir(3);
	SetNpcActionFile("独孤剑", 0, "mpc007_2.asf");
	SetNpcActionFile("独孤剑", 1, "mpc007_2.asf");
	NpcSpecialAction("独孤剑", "mpc007_1.asf");
	Sleep(1500);
	Say("独孤剑：张姑娘，你醒了？", 2);
	Say("绿衣女孩：我这是在哪里……", 28);
	Say("独孤剑：这里是碧霞岛，姑娘刚才与贼人搏斗受了伤。", 1);
	Say("绿衣女孩：我记起来了，采花贼……你……你怎么会在这里？难道……你和他们是一伙的？！", 27);
	Say("独孤剑：姑娘误会了，我……", 8);
	Say("绿衣女孩：没想到你竟是这种人！", 27);
	
	SetNpcActionFile("张琳心", 0, "npc004_st.asf");  
	SetNpcActionFile("张琳心", 1, "npc004_pst.asf");
	NpcSpecialAction("张琳心", "mpc005_3.asf");
	Sleep(3000);
	DelNpc("张琳心");
	AddNpc("npc004_张琳心.ini", 6, 22, 1);
	SetNpcDir("张琳心", 7);
	SaveNpc();
	
	SetNpcActionFile("独孤剑", 0, "npc001_st2.asf");
	SetNpcActionFile("独孤剑", 1, "npc001_sst2.asf");
	NpcSpecialAction("独孤剑", "mpc007_3.asf");
	Sleep(1000);
	Say("独孤剑：张姑娘，你真的误会了！你听我解释……", 8);
	Say("绿衣女孩：哼！如果你不是和他们一伙，那你怎么会知道我在这里？", 27);
	Say("独孤剑：我听到酒楼的人说你被采花贼掳走，就一路跟踪……", 1);
	Sleep(1000);
	FadeOut();
	Say("独孤剑把事情的来龙去脉原原本本地告诉了绿衣女孩。");
	Sleep(1000);
	FadeIn();
	Watch("独孤剑", "张琳心", 0);
	Say("绿衣女孩：……", 22);
	Say("独孤剑：难道你还不相信我吗？我……", 6);
	Say("绿衣女孩：不……不是……", 22);
	Say("绿衣女孩：你为了救我，居然如此费尽心力……我感激得很……", 22);
	Sleep(500);
	NpcGoto("张琳心", 5, 23);
	SetNpcDir("张琳心", 1);
	PlayerGoto(6, 24);
	SetPlayerDir(3);
	Say("绿衣女孩：你我只不过萍水相逢，你……何必为了我，冒这么大的风险？", 22);
	Say("独孤剑：姑娘有难，我怎能不顾？", 4);
	Say("绿衣女孩：那……若是换了他人，你也一样会出手相救啦？", 21);
	Say("独孤剑：那是自然，否则学武又有何用？只不过……", 4);
	Watch("独孤剑", "张琳心", 0);
	Say("绿衣女孩：不过什么？", 22);
	Say("独孤剑：不过……不过张姑娘又与别人不同……", 4);
	Say("绿衣女孩：……", 22);
	Say("独孤剑：如果张姑娘有难，就是刀山火海、龙潭虎穴，我也会去闯一闯！", 4);
	Say("绿衣女孩：你……真是一个傻子！", 22);
	Say("独孤剑：……", 4);
	Say("绿衣女孩：……", 22);
	Sleep(2000);
	
	Say("独孤剑：啊呀！我真糊涂，忘记请教姑娘芳名。", 2);
	Say("绿衣女孩：我叫……张琳心。", 22);
	Say("独孤剑：琳心、琳心……慧质琳心，果然好名！", 2);
	Say("张琳心：……你叫什么名字？", 22);
	NpcSpecialAction("独孤剑", "mpc043.asf");
	Sleep(1500);
	Say("独孤剑：在下衡山独孤剑。", 2);
	Say("张琳心：噗哧！独孤、独孤，真是一个怪姓！", 95);
	Say("独孤剑：“独孤”一姓虽然少见，但是却多出名人。", 2);
	Say("张琳心：哦？", 21);
	Say("独孤剑：像唐朝的独孤皇后，就以贤德闻名，而当年名震江湖的“天心飞仙”四剑客中的“仙剑客”独孤云也是姓独孤……", 2);
	Say("张琳心：独孤云？我听我爹说起过这个人，我爹每次提起他，都是一脸敬重的神色，仿佛他是个很了不起的人物。", 21);
	Say("独孤剑：真的吗？你爹倒是一个识英雄重英雄的人！敢问你爹是谁？", 2);
	Say("张琳心：我爹就是当今殿前都指挥使张风张大人！", 21);
	Say("独孤剑：什么？！你……你是张风的女儿！", 6);
	Say("张琳心：独孤公子，你怎么啦？", 25);
	Say("独孤剑：你……竟是张风的女儿！", 5);
	PlayerGoto(6, 26);
	SetPlayerDir(0);
	SetNpcDir("张琳心", 7);
	Say("独孤剑：张姑娘，你可知我是谁？", 9);
	Say("张琳心：……", 25);
	Say("独孤剑：我就是独孤云的儿子！", 9);
	Say("张琳心：独孤公子，我不明白……", 25);
	Say("独孤剑：你不明白？你回去问问你爹，就什么都明白了！", 9);
	NpcGoto("张琳心", 5, 25);
	SetNpcDir("张琳心", 7);
	Say("张琳心：到底是怎么一回事？", 25);
	Say("独孤剑：你真的不知道？就是你爹——当年的“飞剑客”，害死了我的父亲！", 9);
	Say("张琳心：不！这不可能！", 25);
	Watch("独孤剑", "张琳心", 0);
	Say("独孤剑：这都是我恩师亲口告诉我的，他不会骗我！", 9);
	Say("张琳心：可是……我爹一直都十分敬重……", 26);
	Say("独孤剑：那是他假惺惺！", 9);
	Say("张琳心：……", 26);
	Say("张琳心：你是不是后悔救了我——你杀父仇人的女儿？", 26);
	Say("独孤剑：我后悔……认识了你……", 1);
	Say("张琳心：……", 26);
	
	
	Sleep(1000);
	StopMusic();
	PlayMusic("黑影.mp3");
	PlaySound("特_女救命.wav"); 
	SetPlayerDir(5);
	Say("独孤剑：咦？好像有女子呼救的声音。", 1);
	SetNpcDir("张琳心",5);
	Say("张琳心：那些贼人可能还抓了其他女孩关在这里。", 24);
	PlaySound("特_女救命.wav"); 
	Say("张琳心：声音好象是从东北角传来的。", 24);
	Say("张琳心：我们……过去看看吧。", 24);
	Watch("独孤剑", "张琳心", 0);
	Say("独孤剑：……你受了伤，还是我一个人去吧。", 1);
	Say("张琳心：你既然恨我，又何必管我的死活……", 24);
	Say("独孤剑：我……只是恨你的父亲。", 1);
	Say("张琳心：那又有什么分别？", 24);
	Say("独孤剑：……", 1);
	PlaySound("特_女救命.wav"); 
	Say("张琳心：我已经没事了……里面可能有埋伏，要去……就一起去吧。", 24);
	Say("独孤剑：那……好吧。", 1);
	
	SetNpcKind("张琳心", 3);
	SetNpcRelation("张琳心", 0);
	SetNpcScript("张琳心", "张琳心对话.txt");
	SetNpcMagicLevel("张琳心", "magic016_江南如烟.ini", 2);
	SetNpcMagicLevel("张琳心", "magic017_满城花雨.ini", 2);
	SetNpcMagicLevel("张琳心", "magic019_回风拂柳.ini", 2);
	SetNpcMagicLevel("张琳心", "magic020_清心术.ini", 2);
	SetMapTrap(1, "trap01.txt");
	SetMapTrap(2, "trap02.txt");	
	Assign($Event, 160);
	Memo("天黑后，独孤剑和张琳心听到女子的呼救声，两人开始在山洞里寻找被困的少女。");
	Return;

