scripts.渔夫老王对话.txt:
// 渔夫老王对话

	If ($Event == 150) @Event150;

	Say("老王：公子快去救人吧，可要千万小心哪。", 65);
	Return;

@Event150:
	Say("独孤剑：我已经救出了被采花贼掳去的姑娘，她受了伤，还在山洞里。现在能回去吗？", 1);
	Say("老王：天色已晚，海面风大浪大，现在回去实在是太危险了。", 65);
	Say("独孤剑：那怎么办？", 8);
	Say("老王：还是等明儿天亮以后再回去吧！晚上海面风浪大，恐怕你救的那位姑娘受了伤支撑不住，你就在山洞里升个火挡挡夜风吧。", 65);
	Say("独孤剑：也只好如此了！", 1);
	RunScript("过夜.txt");
	Return;

